CREATE TABLE desk_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('note','reminder','collection')),title text NOT NULL,body text NOT NULL DEFAULT '',collection text NOT NULL DEFAULT '',document_id uuid REFERENCES documents(id),due_at timestamptz,done boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX desk_items_user_idx ON desk_items(user_id,done,due_at);
CREATE TABLE document_seen(user_id uuid NOT NULL REFERENCES users(id),document_id uuid NOT NULL REFERENCES documents(id),seen_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,document_id));
CREATE TABLE bulletins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,body text NOT NULL,severity text NOT NULL CHECK(severity IN ('info','important','urgent')),audience text NOT NULL CHECK(audience IN ('all','admin','registrar','employee')),pinned boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,starts_at timestamptz NOT NULL DEFAULT now(),ends_at timestamptz,version integer NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES users(id));
CREATE TABLE bulletin_ack(user_id uuid NOT NULL REFERENCES users(id),bulletin_id uuid NOT NULL REFERENCES bulletins(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,bulletin_id));
